[asy]
unitsize(0.6 cm);

real upperparab (real x) {
  return (sqrt(4*x));
}

real lowerparab (real x) {
  return (-sqrt(4*x));
}

pair A, B, P, Q, R;

A = (1,0);
B = (5,4);
P = (1.5,upperparab(1.5));
Q = (-1,upperparab(1.5));
R = (-1,4);

draw(A--P--B);
draw(graph(upperparab,0,6));
draw(graph(lowerparab,0,6));
draw((-1,-5)--(-1,5),dashed);
draw(P--Q);
draw(B--R);
draw(B--Q);

dot("$A$", A, S);
dot("$B$", B, E);
dot("$P$", P, SE);
dot("$Q$", Q, W);
dot("$R$", R, W);
[/asy]

